package android.view;
public class View {public static final int VISIBLE=0;public ViewParent parent;public ViewParent getParent(){return parent;}public float translationX;public void setTranslationX(float x){translationX=x;}public ViewPropertyAnimator animate(){return new ViewPropertyAnimator(this);}public int left,top,width=1000,height=1600;private ViewGroup.LayoutParams params;public ViewGroup.LayoutParams getLayoutParams(){return params;}public void setLayoutParams(ViewGroup.LayoutParams p){params=p;}private OnClickListener click;public interface OnClickListener {void onClick(View v);}public void setOnClickListener(OnClickListener l){click=l;}public boolean performClick(){if(click==null)return false;click.onClick(this);return true;}private Object tag;private OnTouchListener listener;public interface OnTouchListener {boolean onTouch(View v,MotionEvent e);}public int getVisibility(){return 0;}public void getLocationOnScreen(int[] p){p[0]=left;p[1]=top;}public int getWidth(){return width;}public int getHeight(){return height;}public void setTag(Object o){tag=o;}public Object getTag(){return tag;}public void setOnTouchListener(OnTouchListener l){listener=l;}public boolean dispatchTouchEvent(MotionEvent e){return listener!=null&&listener.onTouch(this,e);}public void setEnabled(boolean value){}public void setMinimumHeight(int h){}public void setPadding(int l,int t,int r,int b){} }
